mapper.select:
SELECT 
FROM crm_contact
WHERE tenant_id = #{tenantId}
  AND customer_id = #{customerId}
  AND phone_number = #{phoneNumber}
  AND del_flag = '0'

mapper.update:
UPDATE crm_contact
SET status = '已停用',
    update_by = #{updateBy},
    update_time = NOW(),
    version = version + 1
WHERE tenant_id = #{tenantId}
  AND contact_id = #{contactId}
  AND version = #{version}
  AND del_flag = '0'
